                    writer.WriteStartArray("JSDocPropertyTags");
                    foreach (var value in n.JSDocPropertyTags) writer.WriteNumberValue(ids[value]);
                    writer.WriteEndArray();
                    writer.WriteBoolean("IsArrayType", n.IsArrayType);
                    writer.WriteEndObject();
                    break;
                }
                case JSDocParameterOrPropertyTagNode n:
                {
                    writer.WriteString("type", "JSDocParameterOrPropertyTag");
                    writer.WriteStartObject("fields");
                    writer.WriteNumber("TagName", n.TagName is { } valueTagName ? ids[valueTagName] : 0);
                    writer.WriteNumber("Name", n.Name is { } valueName ? ids[valueName] : 0);
                    writer.WriteBoolean("IsBracketed", n.IsBracketed);
                    writer.WriteNumber("TypeExpression", n.TypeExpression is { } valueTypeExpression ? ids[valueTypeExpression] : 0);
                    writer.WriteBoolean("IsNameFirst", n.IsNameFirst);
                    writer.WritePropertyName("Comment");
                    List(writer, n.Comment, ids);
                    writer.WriteEndObject();
                    break;
                }
                default: throw new InvalidDataException("Unknown syntax node");
            }
            writer.WriteEndObject();
        }
        writer.WriteEndArray();
        writer.WriteEndObject();
    }
    private static void List(Utf8JsonWriter writer, NodeList? list, Dictionary<SyntaxNode, int> ids)
    {
        if (list is null) { writer.WriteNullValue(); return; }
        writer.WriteStartObject(); writer.WriteNumber("pos", list.Pos); writer.WriteNumber("end", list.End); writer.WriteStartArray("nodes");
        foreach (var node in list) writer.WriteNumberValue(ids[node]); writer.WriteEndArray(); writer.WriteEndObject();
    }
}
